/*!
 * wega-music-boss.js - OMNIWEGA boss fight add-on for the Wega's Challenge music pack.
 * Load AFTER wega-music.js and BEFORE the game module. It registers three tracks with WegaMusic,
 * one per phase of the fight ("boss1", "boss2", "boss3"), so WegaMusic.init() decodes them with
 * the others: the game moves on to the next part as OMNIWEGA loses health.
 * Track: Pizza Tower OST - "Unexpectancy" Parts 1-3 (the final boss) - supplied by the player.
 * Each part is cut to a section that loops seamlessly (loop points on bar lines, 150 bpm).
 */
(function (global) {
  "use strict";
  var D = global.WEGA_MUSIC_DATA, W = global.WegaMusic;
  if (!D || !W) { if (global.console) console.warn("[wega-music-boss] load wega-music.js first"); return; }
  D.boss1 = {
    title: "Unexpectancy, Part 1 (OMNIWEGA Theme)",
    credit: "Pizza Tower OST - Unexpectancy (final boss)",
    duration: 43.990,
    loopStart: 0.050,
    loopEnd: 43.250,
    gain: 0.5,
    src: "data:audio/mpeg;base64,"
  };
  if (W.tracks.indexOf("boss1") < 0) W.tracks.push("boss1");
  D.boss2 = {
    title: "Unexpectancy, Part 2 (OMNIWEGA Theme)",
    credit: "Pizza Tower OST - Unexpectancy (final boss)",
    duration: 63.190,
    loopStart: 0.050,
    loopEnd: 62.450,
    gain: 0.5,
    src: "data:audio/mpeg;base64,"
  };
  if (W.tracks.indexOf("boss2") < 0) W.tracks.push("boss2");
  D.boss3 = {
    title: "Unexpectancy, Part 3 (OMNIWEGA Theme)",
    credit: "Pizza Tower OST - Unexpectancy (final boss)",
    duration: 77.584,
    loopStart: 0.050,
    loopEnd: 76.850,
    gain: 0.5,
    src: "data:audio/mpeg;base64,"
  };
  if (W.tracks.indexOf("boss3") < 0) W.tracks.push("boss3");
})(typeof window !== "undefined" ? window : globalThis);
